input.command:
cat > ci_iam.tf <<'EOF'
# AWS side of the CI handover: GitHub Actions in platform/ingest authenticates via OIDC
# (no long-lived keys) and assumes one of two roles:
#   - plan  : pull_request runs, read-only on the managed resources
#   - apply : runs on refs/heads/main only, can change the managed resources
#
# NOTE: an account can hold only one OIDC provider per URL. If
# token.actions.githubusercontent.com already exists in this account, import it instead:
#   terraform import aws_iam_openid_connect_provider.github \
#     arn:aws:iam::<account-id>:oidc-provider/token.actions.githubusercontent.com

data "aws_caller_identity" "current" {}

locals {
  github_repo = "platform/ingest"

  state_bucket_arn = "arn:aws:s3:::ingest-terraform-state"
  state_key        = "ingest/terraform.tfstate"

  landing_bucket_arn = aws_s3_bucket.landing.arn
  queue_arn          = aws_sqs_queue.events.arn
  table_arn          = aws_dynamodb_table.checkpoints.arn
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "trust" {
  for_each = {
    # Pull requests (the sub claim for pull_request events is not branch-based).
    plan = "repo:${local.github_repo}:pull_request"
    # Merges to main only.
    apply = "repo:${local.github_repo}:ref:refs/heads/main"
  }

  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = [each.value]
    }
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  assume_role_policy   = data.aws_iam_policy_document.trust["plan"].json
  max_session_duration = 3600
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  assume_role_policy   = data.aws_iam_policy_document.trust["apply"].json
  max_session_duration = 3600
}

# Backend access. Plan needs the lock file too (use_lockfile = true writes <key>.tflock).
data "aws_iam_policy_document" "state_rw" {
  statement {
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = [local.state_key, "${local.state_key}.tflock"]
    }
  }

  statement {
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [
      "${local.state_bucket_arn}/${local.state_key}",
      "${local.state_bucket_arn}/${local.state_key}.tflock",
    ]
  }
}

# Plan: refresh/read of the managed resources only.
data "aws_iam_policy_document" "plan" {
  statement {
    actions = [
      "s3:GetBucket*",
      "s3:GetAccelerateConfiguration",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
      "s3:GetBucketPolicy",
      "s3:ListBucket",
    ]
    resources = [local.landing_bucket_arn]
  }

  statement {
    actions   = ["sqs:GetQueueAttributes", "sqs:ListQueueTags"]
    resources = [local.queue_arn]
  }

  statement {
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [local.table_arn]
  }

  # These APIs have no resource-level support.
  statement {
    actions   = ["sqs:ListQueues", "dynamodb:DescribeLimits"]
    resources = ["*"]
  }
}

# Apply: manage only the three resources in main.tf. No IAM permissions, so the apply
# role cannot escalate itself or alter these roles.
data "aws_iam_policy_document" "apply" {
  statement {
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:ListBucket",
      "s3:GetBucket*",
      "s3:PutBucket*",
      "s3:GetEncryptionConfiguration",
      "s3:PutEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:PutLifecycleConfiguration",
      "s3:GetAccelerateConfiguration",
      "s3:PutAccelerateConfiguration",
      "s3:GetReplicationConfiguration",
      "s3:DeleteBucketPolicy",
    ]
    resources = [local.landing_bucket_arn]
  }

  statement {
    actions   = ["sqs:*"]
    resources = [local.queue_arn]
  }

  statement {
    actions   = ["dynamodb:*"]
    resources = [local.table_arn]
  }

  statement {
    actions   = ["sqs:ListQueues", "dynamodb:DescribeLimits"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ci_plan_state" {
  name   = "terraform-state"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.state_rw.json
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "plan-read"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.plan.json
}

resource "aws_iam_role_policy" "ci_apply_state" {
  name   = "terraform-state"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.state_rw.json
}

resource "aws_iam_role_policy" "ci_apply" {
  name   = "apply"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply.json
}

output "ci_plan_role_arn" {
  value = aws_iam_role.ci_plan.arn
}

output "ci_apply_role_arn" {
  value = aws_iam_role.ci_apply.arn
}
EOF
sed -i '/^data "aws_caller_identity"/,+1d' ci_iam.tf
terraform fmt -check ci_iam.tf; terraform init -backend=false >/dev/null 2>&1 && terraform validate 2>&1 | tail -5

